require('dotenv').config();
const express = require('express');
const path = require('node:path');
const crypto = require('node:crypto');
const bcrypt = require('bcryptjs');
const session = require('express-session');
const PgSession = require('connect-pg-simple')(session);
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { Pool } = require('pg');
const { calculateCommission } = require('./commission');
const { sendUtilityStatus } = require('./whatsapp-cloud');

const app = express();
const production = process.env.NODE_ENV === 'production';
if (!process.env.DATABASE_URL || !process.env.SESSION_SECRET || process.env.SESSION_SECRET.length < 32) {
  console.error('Set DATABASE_URL and a SESSION_SECRET of at least 32 characters in .env.'); process.exit(1);
}
const pool = new Pool({ connectionString: process.env.DATABASE_URL, ssl: process.env.PGSSL === 'true' ? { rejectUnauthorized: true } : undefined });
if (production) app.set('trust proxy', 1);
app.use(helmet({ contentSecurityPolicy: false }));
app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: false, limit: '30kb' }));
app.use(session({
  name: 'ashri.sid', secret: process.env.SESSION_SECRET, resave: false, saveUninitialized: false,
  store: new PgSession({ pool, tableName: 'session', createTableIfMissing: true }),
  cookie: { httpOnly: true, secure: production || process.env.COOKIE_SECURE === 'true', sameSite: 'lax', maxAge: 1000 * 60 * 60 * 8 }
}));
app.use('/api/auth', rateLimit({ windowMs: 15 * 60 * 1000, limit: 20, standardHeaders: true, legacyHeaders: false }));
app.use('/api', rateLimit({ windowMs: 60 * 1000, limit: 180, standardHeaders: true, legacyHeaders: false }));

const asyncRoute = fn => (req,res,next) => Promise.resolve(fn(req,res,next)).catch(next);
const cleanUser = u => ({ id: u.id, memberCode: u.member_code, name: u.full_name, email: u.email, mobile: u.mobile, role: u.role, status: u.status, referralCode: u.referral_code, whatsappOptIn: Boolean(u.whatsapp_opt_in) });
async function audit(client, actor, action, type, id, details={}) { await client.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)', [actor || null, action, type, id == null ? null : String(id), JSON.stringify(details)]); }
function requireAuth(req,res,next){ if(!req.session.user) return res.status(401).json({error:'Authentication required'}); next(); }
function requireRole(...roles){ return (req,res,next)=>{ if(!req.session.user) return res.status(401).json({error:'Authentication required'}); if(!roles.includes(req.session.user.role)) return res.status(403).json({error:'Insufficient permissions'}); next(); }; }
const validEmail = s => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);

app.get('/api/health', asyncRoute(async (req,res)=>{ await pool.query('SELECT 1'); res.json({status:'ok',database:'connected',mode:production?'production':'development'}); }));
app.post('/api/auth/register', asyncRoute(async(req,res)=>{
 const name=String(req.body.name||'').trim(), email=String(req.body.email||'').trim().toLowerCase(), mobile=String(req.body.mobile||'').replace(/\D/g,''), password=String(req.body.password||''), referral=String(req.body.referralCode||'').trim().toUpperCase();
 if(name.length<2||name.length>90||!validEmail(email)||password.length<10||password.length>128|| (mobile && !/^\d{10}$/.test(mobile))) return res.status(400).json({error:'Enter a valid name/email/mobile and password (10–128 characters).'});
 const client=await pool.connect(); try { await client.query('BEGIN'); let referrer=null; if(referral){const r=await client.query('SELECT id FROM users WHERE referral_code=$1 AND status=$2',[referral,'active']); if(!r.rowCount) { await client.query('ROLLBACK'); return res.status(400).json({error:'Referral code is invalid or inactive.'}); } referrer=r.rows[0].id; }
 const hash=await bcrypt.hash(password,12), memberCode='AV-'+new Date().getFullYear()+'-'+crypto.randomBytes(4).toString('hex').toUpperCase(), referralCode='AVR-'+crypto.randomBytes(6).toString('hex').toUpperCase();
 const result=await client.query("INSERT INTO users(member_code,full_name,email,mobile,password_hash,role,status,referral_code,referred_by) VALUES($1,$2,$3,$4,$5,'member','pending',$6,$7) RETURNING *",[memberCode,name,email,mobile||null,hash,referralCode,referrer]); await audit(client,result.rows[0].id,'member_registered','user',result.rows[0].id,{referredBy:referrer}); await client.query('COMMIT'); res.status(201).json({message:'Registration received. Admin verification is required before account activation.',member:cleanUser(result.rows[0])});
 } catch(e){ await client.query('ROLLBACK'); if(e.code==='23505') return res.status(409).json({error:'Email or mobile is already registered.'}); throw e; } finally{client.release();}
}));
app.post('/api/auth/login', asyncRoute(async(req,res)=>{
 const identity=String(req.body.identity||'').trim().toLowerCase(), password=String(req.body.password||''); if(!identity||!password) return res.status(400).json({error:'Email/mobile and password are required.'});
 const q=await pool.query('SELECT * FROM users WHERE lower(email)=lower($1) OR mobile=$1 LIMIT 1',[identity]); const user=q.rows[0]; if(!user||!(await bcrypt.compare(password,user.password_hash))) return res.status(401).json({error:'Invalid credentials.'}); if(user.status!=='active') return res.status(403).json({error:'Account is not active. Please contact the administrator.'});
 await new Promise((resolve,reject)=>req.session.regenerate(err=>err?reject(err):resolve())); req.session.user=cleanUser(user); await new Promise((resolve,reject)=>req.session.save(err=>err?reject(err):resolve())); res.json({message:'Login successful',user:req.session.user,redirect:user.role==='member'?'/member/index.html':'/admin-preview/index.html'});
}));
app.post('/api/auth/logout', requireAuth, asyncRoute(async(req,res)=>{ await new Promise((resolve,reject)=>req.session.destroy(err=>err?reject(err):resolve())); res.clearCookie('ashri.sid',{httpOnly:true,secure:production||process.env.COOKIE_SECURE==='true',sameSite:'lax'}); res.json({message:'Logged out'}); }));
app.get('/api/auth/me', requireAuth,(req,res)=>res.json({user:req.session.user}));
app.put('/api/member/whatsapp-preference', requireRole('member'), asyncRoute(async(req,res)=>{if(typeof req.body.optIn!=='boolean')return res.status(400).json({error:'optIn must be true or false.'});const q=await pool.query('UPDATE users SET whatsapp_opt_in=$1,updated_at=now() WHERE id=$2 RETURNING id,whatsapp_opt_in',[req.body.optIn,req.session.user.id]);req.session.user.whatsappOptIn=q.rows[0].whatsapp_opt_in;await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'whatsapp_preference_updated','user',req.session.user.id,JSON.stringify({optIn:req.body.optIn})]);res.json({optIn:q.rows[0].whatsapp_opt_in,message:req.body.optIn?'WhatsApp alerts enabled. API configuration and approved template are still required.':'WhatsApp alerts disabled.'});}));
app.get('/api/member/profile', requireAuth, asyncRoute(async(req,res)=>{ const q=await pool.query('SELECT id,member_code,full_name,email,mobile,role,status,referral_code,created_at FROM users WHERE id=$1',[req.session.user.id]); res.json({member:cleanUser(q.rows[0]),createdAt:q.rows[0].created_at,referralLink:`${process.env.APP_BASE_URL||''}/register.html?ref=${encodeURIComponent(q.rows[0].referral_code)}`}); }));
app.get('/api/admin/members', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{ const q=await pool.query('SELECT id,member_code,full_name,email,mobile,role,status,referral_code,referred_by,created_at FROM users ORDER BY created_at DESC LIMIT 500'); res.json({members:q.rows.map(cleanUser)}); }));
app.patch('/api/admin/members/:id/status', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{ const status=String(req.body.status||''); if(!['active','suspended','rejected'].includes(status)) return res.status(400).json({error:'Invalid status.'}); const c=await pool.connect(); try{await c.query('BEGIN'); const q=await c.query('UPDATE users SET status=$1,updated_at=now() WHERE id=$2 AND role=\'member\' RETURNING id,member_code,full_name,email,mobile,role,status,referral_code',[status,req.params.id]); if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Member not found.'});} await audit(c,req.session.user.id,'member_status_changed','user',req.params.id,{status}); await c.query('COMMIT'); res.json({member:cleanUser(q.rows[0])});}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();} }));
app.get('/api/admin/affiliate/policy', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{ const q=await pool.query('SELECT * FROM affiliate_policies ORDER BY effective_from DESC,id DESC LIMIT 1'); res.json({policy:q.rows[0]||null}); }));
app.put('/api/admin/affiliate/policy', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{ const b=req.body, type=String(b.commissionType||''), value=Number(b.commissionValue), min=Number(b.minSale||0), hold=Number(b.holdDays||0); if(!['percentage','fixed'].includes(type)||!Number.isFinite(value)||value<0||(type==='percentage'&&value>100)||!Number.isFinite(min)||min<0||!Number.isInteger(hold)||hold<0||hold>365) return res.status(400).json({error:'Invalid commission policy.'}); const c=await pool.connect();try{await c.query('BEGIN');await c.query('UPDATE affiliate_policies SET effective_from=LEAST(effective_from,now()) WHERE effective_from>now()');const q=await c.query('INSERT INTO affiliate_policies(enabled,commission_type,commission_value,min_sale,hold_days,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[Boolean(b.enabled),type,value,min,hold,req.session.user.id]);await audit(c,req.session.user.id,'affiliate_policy_created','affiliate_policy',q.rows[0].id,{type,value,min,hold});await c.query('COMMIT');res.status(201).json({policy:q.rows[0]});}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();} }));
app.post('/api/internal/orders/verified-paid', asyncRoute(async(req,res)=>{
 const secret=process.env.PAYMENT_WEBHOOK_SECRET;
 const provided=Buffer.from(String(req.get('x-payment-webhook-secret')||'')); const expected=Buffer.from(secret||''); if(!secret || provided.length!==expected.length || !crypto.timingSafeEqual(provided,expected)) return res.status(401).json({error:'Invalid payment webhook credentials.'});
 const orderRef=String(req.body.orderRef||'').trim(), referralCode=String(req.body.referralCode||'').trim().toUpperCase(), gross=Number(req.body.grossAmount), eligible=Number(req.body.eligibleAmount);
 if(!orderRef||orderRef.length>100||!Number.isFinite(gross)||gross<=0||!Number.isFinite(eligible)||eligible<0||eligible>gross) return res.status(400).json({error:'Invalid verified order payload.'});
 const c=await pool.connect(); try { await c.query('BEGIN'); const dup=await c.query('SELECT id FROM orders WHERE order_ref=$1',[orderRef]); if(dup.rowCount){await c.query('ROLLBACK');return res.status(409).json({error:'Order already processed; duplicate commission prevented.'});}
 let referrer=null; if(referralCode){const r=await c.query("SELECT id FROM users WHERE referral_code=$1 AND status='active' AND role='member'",[referralCode]); if(r.rowCount)referrer=r.rows[0].id;}
 const o=await c.query("INSERT INTO orders(order_ref,referred_by,gross_amount,eligible_amount,payment_status,paid_at) VALUES($1,$2,$3,$4,'paid',now()) RETURNING *",[orderRef,referrer,gross,eligible]); let commission=null;
 if(referrer && eligible>0){const pol=await c.query('SELECT * FROM affiliate_policies WHERE enabled=true AND effective_from<=now() ORDER BY effective_from DESC,id DESC LIMIT 1'); if(pol.rowCount){const p=pol.rows[0]; if(eligible>=Number(p.min_sale)){const amount=calculateCommission(eligible,p); const result=await c.query("INSERT INTO commission_ledger(order_id,member_id,policy_id,eligible_sale,commission_amount,status) VALUES($1,$2,$3,$4,$5,'pending') ON CONFLICT(order_id) DO NOTHING RETURNING *",[o.rows[0].id,referrer,p.id,eligible,amount]); commission=result.rows[0]||null;}}}
 await audit(c,null,'verified_paid_order_recorded','order',o.rows[0].id,{orderRef,referrer,commissionCreated:Boolean(commission)}); await c.query('COMMIT'); res.status(201).json({order:{id:o.rows[0].id,orderRef:o.rows[0].order_ref,paymentStatus:o.rows[0].payment_status},commission:commission?{amount:commission.commission_amount,status:commission.status}:null});
 }catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}
}));
app.get('/api/member/affiliate/report', requireRole('member'), asyncRoute(async(req,res)=>{
 const q=await pool.query(`SELECT o.order_ref,o.created_at,o.paid_at,o.eligible_amount,c.commission_amount,c.status,c.payout_reference,c.review_note FROM commission_ledger c JOIN orders o ON o.id=c.order_id WHERE c.member_id=$1 ORDER BY c.created_at DESC LIMIT 1000`,[req.session.user.id]);
 const summary=await pool.query(`SELECT count(*)::int AS referred_orders,COALESCE(sum(o.eligible_amount),0) AS eligible_sales,COALESCE(sum(c.commission_amount),0) AS commission_total,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='pending'),0) AS pending_commission,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='approved'),0) AS approved_commission,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='paid'),0) AS paid_commission FROM commission_ledger c JOIN orders o ON o.id=c.order_id WHERE c.member_id=$1`,[req.session.user.id]);
 const referrals=await pool.query(`SELECT count(*)::int AS total_referrals,count(*) FILTER(WHERE status='active')::int AS active_referrals FROM users WHERE referred_by=$1`,[req.session.user.id]);
 res.json({records:q.rows,summary:summary.rows[0],referrals:referrals.rows[0]});
}));
app.get('/api/member/affiliate/policy', requireRole('member'), asyncRoute(async(req,res)=>{const q=await pool.query('SELECT enabled,commission_type,commission_value,min_sale,hold_days,effective_from FROM affiliate_policies WHERE effective_from<=now() ORDER BY effective_from DESC,id DESC LIMIT 1');res.json({policy:q.rows[0]||null});}));
app.get('/api/admin/affiliate/report', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{
 const params=[],where=[];const add=(sql,v)=>{params.push(v);where.push(sql.replace('?',`$${params.length}`))};
 if(req.query.status && ['pending','approved','rejected','paid','reversed'].includes(String(req.query.status)))add('c.status = ?',String(req.query.status));
 if(req.query.from && /^\d{4}-\d{2}-\d{2}$/.test(String(req.query.from)))add('o.created_at >= ?::date',String(req.query.from));
 if(req.query.to && /^\d{4}-\d{2}-\d{2}$/.test(String(req.query.to)))add("o.created_at < (?::date + interval '1 day')",String(req.query.to));
 if(req.query.memberCode && /^[A-Za-z0-9_-]{2,40}$/.test(String(req.query.memberCode)))add('u.member_code = ?',String(req.query.memberCode));
 const sql=`SELECT o.id AS order_id,u.id AS member_id,u.member_code,u.full_name,u.email,u.referral_code,o.order_ref,o.created_at,o.paid_at,o.gross_amount,o.eligible_amount,c.commission_amount,c.status,c.payout_reference,c.review_note,c.created_at AS commission_created_at FROM commission_ledger c JOIN orders o ON o.id=c.order_id JOIN users u ON u.id=c.member_id ${where.length?'WHERE '+where.join(' AND '):''} ORDER BY c.created_at DESC LIMIT 5000`;
 const q=await pool.query(sql,params);res.json({records:q.rows,filters:{status:req.query.status||null,from:req.query.from||null,to:req.query.to||null,memberCode:req.query.memberCode||null}});
}));
app.get('/api/admin/affiliate/summary', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{
 const q=await pool.query(`SELECT count(DISTINCT u.id)::int AS affiliates,count(DISTINCT o.id)::int AS referred_orders,COALESCE(sum(o.gross_amount),0) AS gross_sales,COALESCE(sum(o.eligible_amount),0) AS eligible_sales,COALESCE(sum(c.commission_amount),0) AS commission_total,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='pending'),0) AS pending_commission,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='approved'),0) AS approved_commission,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='paid'),0) AS paid_commission,COALESCE(sum(c.commission_amount) FILTER(WHERE c.status='reversed'),0) AS reversed_commission FROM users u LEFT JOIN orders o ON o.referred_by=u.id AND o.payment_status='paid' LEFT JOIN commission_ledger c ON c.order_id=o.id WHERE u.role='member'`);
 const counts=await pool.query(`SELECT count(*) FILTER(WHERE referred_by IS NOT NULL)::int AS referred_members,count(*) FILTER(WHERE referred_by IS NOT NULL AND status='active')::int AS active_referred_members FROM users`);res.json({summary:q.rows[0],referrals:counts.rows[0]});
}));
app.get('/api/admin/affiliate/referrals', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{const q=await pool.query(`SELECT referrer.id AS member_id,referrer.member_code,referrer.full_name,referrer.referral_code,COALESCE(signups.signup_count,0)::int AS signup_count,COALESCE(signups.active_signups,0)::int AS active_signups,COALESCE(sales.paid_orders,0)::int AS paid_orders,COALESCE(sales.eligible_sales,0) AS eligible_sales,COALESCE(sales.commission_total,0) AS commission_total FROM users referrer LEFT JOIN LATERAL (SELECT count(*) AS signup_count,count(*) FILTER(WHERE status='active') AS active_signups FROM users WHERE referred_by=referrer.id) signups ON true LEFT JOIN LATERAL (SELECT count(DISTINCT o.id) AS paid_orders,COALESCE(sum(o.eligible_amount),0) AS eligible_sales,COALESCE(sum(c.commission_amount),0) AS commission_total FROM orders o LEFT JOIN commission_ledger c ON c.order_id=o.id WHERE o.referred_by=referrer.id AND o.payment_status='paid') sales ON true WHERE referrer.role='member' ORDER BY signup_count DESC,eligible_sales DESC LIMIT 5000`);res.json({records:q.rows});}));
app.post('/api/admin/orders/:id/commission/review', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{const status=String(req.body.status||''),note=String(req.body.note||'').slice(0,500);if(!['approved','rejected'].includes(status))return res.status(400).json({error:'Status must be approved or rejected.'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query('UPDATE commission_ledger SET status=$1,reviewed_by=$2,review_note=$3,updated_at=now() WHERE order_id=$4 AND status=\'pending\' RETURNING *',[status,req.session.user.id,note,req.params.id]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Pending commission not found.'});}await audit(c,req.session.user.id,'commission_reviewed','commission',q.rows[0].id,{status,note});await c.query('COMMIT');res.json({commission:q.rows[0]});}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}}));
app.post('/api/member/family-support', requireRole('member'), asyncRoute(async(req,res)=>{const amount=Number(req.body.amount),reason=String(req.body.reason||'').trim();if(!Number.isFinite(amount)||amount<=0||amount>1000000||reason.length<10||reason.length>3000||req.body.consent!==true)return res.status(400).json({error:'Enter a valid amount, reason (10–3000 characters) and confirm consent.'});const ref='FS-'+crypto.randomBytes(5).toString('hex').toUpperCase();const q=await pool.query('INSERT INTO family_support_applications(application_ref,member_id,requested_amount,reason,consent_at) VALUES($1,$2,$3,$4,now()) RETURNING application_ref,requested_amount,status,created_at',[ref,req.session.user.id,amount,reason]);res.status(201).json({application:q.rows[0],message:'Application submitted for review; this does not guarantee assistance.'});}));
