app.get('/api/admin/family-support', requireRole('super_admin','admin','support_staff'), asyncRoute(async(req,res)=>{const q=await pool.query(`SELECT a.application_ref,a.member_id,u.member_code,u.full_name,a.requested_amount,a.reason,a.status,a.decision_note,a.approved_amount,a.created_at FROM family_support_applications a JOIN users u ON u.id=a.member_id ORDER BY a.created_at DESC LIMIT 500`);res.json({applications:q.rows});}));
app.patch('/api/admin/family-support/:ref', requireRole('super_admin','admin'), asyncRoute(async(req,res)=>{const status=String(req.body.status||''),note=String(req.body.note||'').slice(0,1000),approved=req.body.approvedAmount==null?null:Number(req.body.approvedAmount);if(!['under_review','approved','rejected'].includes(status)||(status==='approved'&&(!Number.isFinite(approved)||approved<=0)))return res.status(400).json({error:'Invalid decision or approved amount.'});const q=await pool.query('UPDATE family_support_applications SET status=$1,decision_by=$2,decision_note=$3,approved_amount=$4,updated_at=now() WHERE application_ref=$5 RETURNING *',[status,req.session.user.id,note,approved,req.params.ref]);if(!q.rowCount)return res.status(404).json({error:'Application not found.'});await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'family_support_decision','family_support',req.params.ref,JSON.stringify({status,approved,note})]);res.json({application:q.rows[0]});}));

app.post('/api/member/payout-requests',requireRole('member'),asyncRoute(async(req,res)=>{const amount=Number(req.body.amount),method=String(req.body.paymentMethod||'').trim(),details=req.body.paymentDetails&&typeof req.body.paymentDetails==='object'&&!Array.isArray(req.body.paymentDetails)?req.body.paymentDetails:{};if(!Number.isFinite(amount)||amount<=0||amount>10000000||!textField(method,2,60)||JSON.stringify(details).length>3000)return res.status(400).json({error:'Invalid payout request.'});const q=await pool.query('INSERT INTO payout_requests(member_id,amount,payment_method,payment_details) VALUES($1,$2,$3,$4) RETURNING id,amount,payment_method,status,created_at',[req.session.user.id,amount,method,JSON.stringify(details)]);await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'payout_requested','payout',q.rows[0].id]);res.status(201).json({payout:q.rows[0]});}));
