// V18 Admin API modules. All writes are authenticated, role-checked, validated and audited.
const adminOnly = requireRole('super_admin','admin');
const asId = v => /^\d+$/.test(String(v||'')) && Number(v)>0;
const textField = (v,min,max) => typeof v==='string' && v.trim().length>=min && v.trim().length<=max;
async function auditedWrite(req,res,action,type,id,sql,params){ const c=await pool.connect(); try { await c.query('BEGIN'); const q=await c.query(sql,params); if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Record not found.'});} await audit(c,req.session.user.id,action,type,id??q.rows[0].id,{}); await c.query('COMMIT'); return res.json({record:q.rows[0]}); } catch(e){await c.query('ROLLBACK');throw e;} finally{c.release();} }
app.get('/api/admin/dashboard',adminOnly,asyncRoute(async(req,res)=>{const q=await pool.query(`SELECT (SELECT count(*) FROM users WHERE role='member') members,(SELECT count(*) FROM users WHERE role='member' AND status='active') active_members,(SELECT count(*) FROM orders) orders,(SELECT COALESCE(sum(gross_amount),0) FROM orders WHERE payment_status='paid') paid_revenue,(SELECT count(*) FROM orders WHERE payment_status='pending') pending_orders,(SELECT count(*) FROM commission_ledger WHERE status='pending') pending_commissions,(SELECT count(*) FROM payout_requests WHERE status='requested') payout_requests,(SELECT count(*) FROM support_tickets WHERE status IN ('open','in_progress')) open_tickets`);res.json({stats:q.rows[0]});}));
app.get('/api/admin/products',adminOnly,asyncRoute(async(req,res)=>{const q=await pool.query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC LIMIT 1000');res.json({products:q.rows});}));
app.post('/api/admin/categories',adminOnly,asyncRoute(async(req,res)=>{const name=String(req.body.name||'').trim(),description=String(req.body.description||'').trim();if(!textField(name,2,100)||description.length>1000)return res.status(400).json({error:'Invalid category name or description.'});const q=await pool.query('INSERT INTO categories(name,description) VALUES($1,$2) RETURNING *',[name,description]);await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'category_created','category',q.rows[0].id]);res.status(201).json({category:q.rows[0]});}));
app.get('/api/admin/categories',adminOnly,asyncRoute(async(req,res)=>{const q=await pool.query('SELECT * FROM categories ORDER BY name');res.json({categories:q.rows});}));
app.post('/api/admin/products',adminOnly,asyncRoute(async(req,res)=>{const b=req.body,sku=String(b.sku||'').trim(),name=String(b.name||'').trim(),price=Number(b.price),stock=Number(b.stockQty||0),cat=b.categoryId==null?null:Number(b.categoryId);if(!textField(sku,1,60)||!textField(name,2,160)||!Number.isFinite(price)||price<0||!Number.isInteger(stock)||stock<0||(cat!==null&&(!Number.isInteger(cat)||cat<1)))return res.status(400).json({error:'Invalid product fields.'});const q=await pool.query('INSERT INTO products(category_id,sku,name,description,price,stock_qty,active) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *',[cat,sku,name,String(b.description||'').slice(0,4000),price,stock,b.active!==false]);await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'product_created','product',q.rows[0].id]);res.status(201).json({product:q.rows[0]});}));
app.patch('/api/admin/products/:id',adminOnly,asyncRoute(async(req,res)=>{if(!asId(req.params.id))return res.status(400).json({error:'Invalid product id.'});const b=req.body,price=Number(b.price),stock=Number(b.stockQty);if(!textField(String(b.name||''),2,160)||!Number.isFinite(price)||price<0||!Number.isInteger(stock)||stock<0)return res.status(400).json({error:'Invalid product fields.'});const q=await pool.query('UPDATE products SET name=$1,description=$2,price=$3,stock_qty=$4,active=$5,updated_at=now() WHERE id=$6 RETURNING *',[String(b.name).trim(),String(b.description||'').slice(0,4000),price,stock,b.active!==false,req.params.id]);if(!q.rowCount)return res.status(404).json({error:'Product not found.'});await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'product_updated','product',req.params.id]);res.json({product:q.rows[0]});}));
app.get('/api/admin/orders',adminOnly,asyncRoute(async(req,res)=>{const q=await pool.query('SELECT o.*,u.member_code,u.full_name FROM orders o LEFT JOIN users u ON u.id=o.referred_by ORDER BY o.created_at DESC LIMIT 1000');res.json({orders:q.rows});}));
app.post('/api/admin/orders/:id/cancel',adminOnly,asyncRoute(async(req,res)=>{if(!asId(req.params.id))return res.status(400).json({error:'Invalid order id.'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("UPDATE orders SET payment_status='cancelled' WHERE id=$1 AND payment_status IN ('pending','paid') RETURNING *",[req.params.id]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(409).json({error:'Order not found or cannot be cancelled.'});}await c.query("UPDATE commission_ledger SET status='reversed',updated_at=now() WHERE order_id=$1 AND status IN ('pending','approved')",[req.params.id]);await audit(c,req.session.user.id,'order_cancelled','order',req.params.id,{});await c.query('COMMIT');res.json({order:q.rows[0]});}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}}));
app.get('/api/admin/refunds',adminOnly,asyncRoute(async(req,res)=>{const q=await pool.query('SELECT r.*,o.order_ref FROM refunds r JOIN orders o ON o.id=r.order_id ORDER BY r.created_at DESC LIMIT 1000');res.json({refunds:q.rows});}));
app.post('/api/admin/refunds',adminOnly,asyncRoute(async(req,res)=>{const orderId=Number(req.body.orderId),amount=Number(req.body.amount),reason=String(req.body.reason||'').trim();if(!Number.isInteger(orderId)||orderId<1||!Number.isFinite(amount)||amount<=0||!textField(reason,5,1000))return res.status(400).json({error:'Invalid refund request.'});const o=await pool.query("SELECT id,gross_amount,payment_status FROM orders WHERE id=$1 AND payment_status IN ('paid','refunded')",[orderId]);if(!o.rowCount||amount>Number(o.rows[0].gross_amount))return res.status(400).json({error:'Order is not refundable or amount exceeds order total.'});const q=await pool.query('INSERT INTO refunds(order_id,amount,reason) VALUES($1,$2,$3) RETURNING *',[orderId,amount,reason]);await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES($1,$2,$3,$4)',[req.session.user.id,'refund_requested','refund',q.rows[0].id]);res.status(201).json({refund:q.rows[0]});}));
app.patch('/api/admin/refunds/:id',adminOnly,asyncRoute(async(req,res)=>{const status=String(req.body.status||'');if(!asId(req.params.id)||!['approved','rejected','processed'].includes(status))return res.status(400).json({error:'Invalid refund action.'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query('UPDATE refunds SET status=$1,reviewed_by=$2,payment_reference=$3,updated_at=now() WHERE id=$4 AND status IN (\'requested\',\'approved\') RETURNING *',[status,req.session.user.id,String(req.body.paymentReference||'').slice(0,160)||null,req.params.id]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Refund request not found.'});}if(status==='processed'){await c.query("UPDATE orders SET payment_status='refunded' WHERE id=$1",[q.rows[0].order_id]);await c.query("UPDATE commission_ledger SET status='reversed',updated_at=now() WHERE order_id=$1 AND status IN ('pending','approved')",[q.rows[0].order_id]);}await audit(c,req.session.user.id,'refund_status_changed','refund',req.params.id,{status});await c.query('COMMIT');res.json({refund:q.rows[0]});}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}}));
// V20: Business plan builder (server-validated and database-backed)
app.get('/api/admin/business-plans',adminOnly,asyncRoute(async(req,res)=>{const q=await pool.query('SELECT * FROM business_plan_packages ORDER BY id');res.json({packages:q.rows});}));
app.post('/api/admin/business-plans',adminOnly,asyncRoute(async(req,res)=>{const b=req.body,key=String(b.packageKey||'').trim().toLowerCase(),name=String(b.name||'').trim(),price=Number(b.basePrice),gst=Number(b.gstPercent);if(!/^[a-z0-9_-]{2,50}$/.test(key)||!textField(name,2,120)||!Number.isFinite(price)||price<0||price>100000000||!Number.isFinite(gst)||gst<0||gst>100)return res.status(400).json({error:'Invalid package key, name, price or GST.'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query('INSERT INTO business_plan_packages(package_key,name,description,base_price,gst_percent,active,is_free,eligibility_rules,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,$9) RETURNING *',[key,name,String(b.description||'').slice(0,3000),price,gst,b.active!==false,b.isFree===true,JSON.stringify(b.eligibilityRules&&typeof b.eligibilityRules==='object'&&!Array.isArray(b.eligibilityRules)?b.eligibilityRules:{}),req.session.user.id]);await audit(c,req.session.user.id,'business_package_created','business_plan_package',q.rows[0].id,{key,name,price,gst});await c.query('COMMIT');res.status(201).json({package:q.rows[0]});}catch(e){await c.query('ROLLBACK');if(e.code==='23505')return res.status(409).json({error:'Package key already exists.'});throw e;}finally{c.release();}}));
app.put('/api/admin/business-plans/:id',adminOnly,asyncRoute(async(req,res)=>{if(!asId(req.params.id))return res.status(400).json({error:'Invalid package id.'});const b=req.body,name=String(b.name||'').trim(),price=Number(b.basePrice),gst=Number(b.gstPercent);if(!textField(name,2,120)||!Number.isFinite(price)||price<0||price>100000000||!Number.isFinite(gst)||gst<0||gst>100)return res.status(400).json({error:'Invalid package fields.'});const q=await pool.query('UPDATE business_plan_packages SET name=$1,description=$2,base_price=$3,gst_percent=$4,active=$5,is_free=$6,eligibility_rules=$7,updated_by=$8,updated_at=now() WHERE id=$9 RETURNING *',[name,String(b.description||'').slice(0,3000),price,gst,b.active!==false,b.isFree===true,JSON.stringify(b.eligibilityRules&&typeof b.eligibilityRules==='object'&&!Array.isArray(b.eligibilityRules)?b.eligibilityRules:{}),req.session.user.id,req.params.id]);if(!q.rowCount)return res.status(404).json({error:'Package not found.'});await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'business_package_updated','business_plan_package',req.params.id,JSON.stringify({name,price,gst})]);res.json({package:q.rows[0]});}));
app.get('/api/admin/business-plans/:id/levels',adminOnly,asyncRoute(async(req,res)=>{if(!asId(req.params.id))return res.status(400).json({error:'Invalid package id.'});const q=await pool.query('SELECT * FROM business_plan_levels WHERE package_id=$1 ORDER BY level_no',[req.params.id]);res.json({levels:q.rows});}));
app.put('/api/admin/business-plans/:id/levels/:levelNo',adminOnly,asyncRoute(async(req,res)=>{const packageId=Number(req.params.id),levelNo=Number(req.params.levelNo),b=req.body,name=String(b.levelName||'').trim(),qual=Number(b.qualifyingIds||0),amount=Number(b.rewardAmount||0),type=String(b.rewardType||'none');if(!Number.isInteger(packageId)||packageId<1||!Number.isInteger(levelNo)||levelNo<1||levelNo>20||!textField(name,2,100)||!Number.isInteger(qual)||qual<0||!['cash','product','status','none'].includes(type)||!Number.isFinite(amount)||amount<0||amount>100000000)return res.status(400).json({error:'Invalid level settings.'});const q=await pool.query('INSERT INTO business_plan_levels(package_id,level_no,level_name,qualifying_ids,reward_type,reward_amount,reward_label,notes,active) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(package_id,level_no) DO UPDATE SET level_name=EXCLUDED.level_name,qualifying_ids=EXCLUDED.qualifying_ids,reward_type=EXCLUDED.reward_type,reward_amount=EXCLUDED.reward_amount,reward_label=EXCLUDED.reward_label,notes=EXCLUDED.notes,active=EXCLUDED.active,updated_at=now() RETURNING *',[packageId,levelNo,name,qual,type,amount,String(b.rewardLabel||'').slice(0,160),String(b.notes||'').slice(0,1000),b.active!==false]);await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'business_plan_level_updated','business_plan_level',q.rows[0].id,JSON.stringify({packageId,levelNo,name,qual,type,amount})]);res.json({level:q.rows[0]});}));
app.post('/api/business-plans/calculate',asyncRoute(async(req,res)=>{const price=Number(req.body.basePrice),gst=Number(req.body.gstPercent);if(!Number.isFinite(price)||price<0||price>100000000||!Number.isFinite(gst)||gst<0||gst>100)return res.status(400).json({error:'Enter a valid base price and GST percentage.'});const tax=Math.round((price*gst/100+Number.EPSILON)*100)/100;res.json({basePrice:price,gstPercent:gst,gstAmount:tax,totalPrice:Math.round((price+tax+Number.EPSILON)*100)/100,currency:'INR'});}));
