app.patch('/api/admin/payouts/:id',adminOnly,asyncRoute(async(req,res)=>{const status=String(req.body.status||''),ref=String(req.body.paymentReference||'').slice(0,160),note=String(req.body.note||'').slice(0,500);if(!asId(req.params.id)||!['approved','rejected','paid'].includes(status)||(status==='paid'&&!ref))return res.status(400).json({error:'Invalid payout status; payment reference required when marking paid.'});const c=await pool.connect();try{await c.query('BEGIN');const q=await c.query("UPDATE payout_requests SET status=$1,reviewed_by=$2,payment_reference=$3,note=$4,updated_at=now() WHERE id=$5 AND status IN ('requested','approved') RETURNING *",[status,req.session.user.id,ref||null,note,req.params.id]);if(!q.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Payout request not found.'});}await audit(c,req.session.user.id,'payout_status_changed','payout',req.params.id,{status});await c.query('COMMIT');res.json({payout:q.rows[0]});}catch(e){await c.query('ROLLBACK');throw e;}finally{c.release();}}));
