app.put('/api/admin/permissions/:role/:permission',requireRole('super_admin'),asyncRoute(async(req,res)=>{const role=String(req.params.role),permission=String(req.params.permission);if(!['admin','member','support_staff','super_admin'].includes(role)||!/^[a-z][a-z0-9_.-]{1,80}$/i.test(permission)||typeof req.body.allowed!=='boolean'||(role==='super_admin'&&req.body.allowed===false))return res.status(400).json({error:'Invalid permission update.'});const q=await pool.query('INSERT INTO role_permissions(role,permission,allowed,updated_by) VALUES($1,$2,$3,$4) ON CONFLICT(role,permission) DO UPDATE SET allowed=EXCLUDED.allowed,updated_by=EXCLUDED.updated_by,updated_at=now() RETURNING *',[role,permission,req.body.allowed,req.session.user.id]);await pool.query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[req.session.user.id,'role_permission_updated','permission',`${role}:${permission}`,JSON.stringify({allowed:req.body.allowed})]);res.json({permission:q.rows[0]});}));
app.get('/api/admin/audit-logs',requireRole('super_admin','admin'),asyncRoute(async(req,res)=>{const limit=Math.min(1000,Math.max(1,Number(req.query.limit)||200));const q=await pool.query('SELECT a.*,u.email actor_email,u.role actor_role FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT $1',[limit]);res.json({logs:q.rows});}));
app.get('/api/admin/reports.csv',adminOnly,asyncRoute(async(req,res)=>{const type=String(req.query.type||'orders');const configs={orders:['SELECT order_ref,gross_amount,eligible_amount,payment_status,created_at FROM orders ORDER BY created_at DESC LIMIT 10000',['order_ref','gross_amount','eligible_amount','payment_status','created_at']],members:["SELECT member_code,full_name,email,role,status,created_at FROM users ORDER BY created_at DESC LIMIT 10000",['member_code','full_name','email','role','status','created_at']],commissions:["SELECT u.member_code,o.order_ref,c.eligible_sale,c.commission_amount,c.status,c.created_at FROM commission_ledger c JOIN users u ON u.id=c.member_id JOIN orders o ON o.id=c.order_id ORDER BY c.created_at DESC LIMIT 10000",['member_code','order_ref','eligible_sale','commission_amount','status','created_at']]};if(type==='referrals')configs.referrals=["SELECT u.member_code,u.full_name,u.referral_code,count(r.id)::int AS signup_count,count(r.id) FILTER(WHERE r.status='active')::int AS active_signups FROM users u LEFT JOIN users r ON r.referred_by=u.id WHERE u.role='member' GROUP BY u.id ORDER BY signup_count DESC LIMIT 10000",['member_code','full_name','referral_code','signup_count','active_signups']];if(!configs[type])return res.status(400).json({error:'Report type must be orders, members, commissions, or referrals.'});const [sql,cols]=configs[type],q=await pool.query(sql);const esc=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"';const csv=[cols.join(','),...q.rows.map(r=>cols.map(k=>esc(r[k])).join(','))].join('\r\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename="ashri-${type}-report.csv"`);res.send(csv);}));

// V22 Utility Services APIs. Provider secrets are environment-only; never return them to clients.
const utilityCategories = ['recharge','bill_payment','banking','money_transfer','travel','insurance','education','subscription','other'];
const utilityText = (v,min,max)=>typeof v==='string'&&v.trim().length>=min&&v.trim().length<=max;
app.get('/api/utility/services', requireAuth, asyncRoute(async(req,res)=>{const q=await pool.query("SELECT id,service_key,name,category,description,mode,input_schema FROM utility_services WHERE active=true AND test_mode=false ORDER BY category,name");res.json({services:q.rows});}));
